<?php
declare(strict_types=1);
namespace App\Controllers;
use PDO;use App\Core\Auth;use App\Core\Database;use App\Core\Security;use App\Core\View;use App\Services\AuditService;use App\Services\NotificationService;use App\Services\MailerService;use App\Services\PermissionService;use App\Services\WorkflowService;use App\Support\Jalali;use App\Services\SpreadsheetService;use App\Services\RahkaranPriceService;
final class AdvancedController{
 private function guard(string $p):void{Auth::requireLogin();PermissionService::require(Auth::userId(),$p);}
 private function csv(array $rows,array $headers,string $name):never{
  header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment; filename="'.$name.'"');echo "\xEF\xBB\xBF";$o=fopen('php://output','wb');fputcsv($o,$headers);foreach($rows as $r)fputcsv($o,$r);fclose($o);exit;
 }
 public function apiDocs():void{$this->guard('api.docs.view');View::render('advanced/api-docs');}
 public function search():void{$this->guard('search.view');$pdo=Database::connection();$q=trim((string)($_GET['q']??''));$category=(int)($_GET['category_id']??0);$unit=(int)($_GET['unit_id']??0);$importance=(int)($_GET['importance']??0);$status=(string)($_GET['status']??'active');$age=(int)($_GET['age']??0);$min=(string)($_GET['min_price']??'');$max=(string)($_GET['max_price']??'');$where=['1=1'];$p=[];if($q!==''){$where[]='(p.product_code LIKE :q OR p.product_name LIKE :q)';$p['q']='%'.$q.'%';}if($category){$where[]='p.category_id=:cat';$p['cat']=$category;}if($unit){$where[]='p.unit_id=:unit';$p['unit']=$unit;}if($importance){$where[]='p.importance=:imp';$p['imp']=$importance;}if($status==='active')$where[]="p.is_active=1";elseif($status==='inactive')$where[]="p.is_active=0";if($age>0){$where[]="EXISTS(SELECT 1 FROM product_prices ap WHERE ap.product_id=p.id AND ap.price_received_at<=DATEADD(DAY,-:age,SYSDATETIME()))";$p['age']=$age;}if($min!==''){$where[]="EXISTS(SELECT 1 FROM product_prices bp WHERE bp.product_id=p.id AND bp.unit_price>=:minp)";$p['minp']=(float)$min;}if($max!==''){$where[]="EXISTS(SELECT 1 FROM product_prices cp WHERE cp.product_id=p.id AND cp.unit_price<=:maxp)";$p['maxp']=(float)$max;}$sql="SELECT TOP 500 p.id,p.product_code,p.product_name,p.importance,p.is_active,p.status,c.name category_name,u.name unit_name,(SELECT MAX(x.price_received_at) FROM product_prices x WHERE x.product_id=p.id) latest_date,(SELECT MAX(x.unit_price) FROM product_prices x WHERE x.product_id=p.id) latest_unit_price FROM products p LEFT JOIN product_categories c ON c.id=p.category_id JOIN units u ON u.id=p.unit_id WHERE ".implode(' AND ',$where)." ORDER BY p.product_code";$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();$categories=$pdo->query('SELECT id,name FROM product_categories WHERE is_active=1 ORDER BY name')->fetchAll();$units=$pdo->query('SELECT id,name FROM units WHERE is_active=1 ORDER BY name')->fetchAll();$s=$pdo->prepare('SELECT id,name,filter_json FROM saved_filters WHERE user_id=:u AND screen=:s ORDER BY name');$s->execute(['u'=>Auth::userId(),'s'=>'search']);$filters=$s->fetchAll();View::render('advanced/search',compact('rows','categories','units','q','category','unit','importance','status','age','min','max','filters'));}
 public function bulk():void{$this->guard('products.bulk');$companies=Database::connection()->query('SELECT id, listcode, listname FROM dbo.SupplierCO ORDER BY listname')->fetchAll(PDO::FETCH_ASSOC);$selectedCode=trim((string)($_GET['code']??''));$selectedCompanyName='';foreach($companies as $company){if(trim((string)($company['listcode']??''))===$selectedCode){$selectedCompanyName=(string)$company['listname'];break;}}$validCodes=array_map(static fn(array $row):string=>trim((string)($row['listcode']??'')),$companies);$members=[];$loadError='';$paymentAgreements=[];if($selectedCode!==''&&in_array($selectedCode,$validCodes,true)){try{$service=RahkaranPriceService::instance();$members=$service->partGroupMembers($selectedCode);$paymentAgreements=$service->paymentAgreements();$codes=array_values(array_unique(array_filter(array_map(static fn(array $m):string=>trim((string)($m['code']??'')),$members))));$rahkaranRows=$service->rowsByCodes($codes);$expertsByCode=$service->expertsByCodes($codes);foreach($members as &$member){$code=trim((string)($member['code']??''));$r=$rahkaranRows[$code]??[];$member['secondcode']=(string)($r['secondcode']??'');$member['expert']=(string)($expertsByCode[$code]??'');$member['unit_id']=(int)($r['Announcement_unit_id']??0);$member['unit_name']=(string)($r['Announcement_unit']??'');}unset($member);}catch(\Throwable $e){error_log('Rahkaran company members failed: '.$e->getMessage());$loadError='دریافت اقلام یا توافق‌های پرداخت از دیتابیس ناموفق بود.';}}else{$selectedCode='';$selectedCompanyName='';}View::render('advanced/bulk',compact('companies','selectedCode','selectedCompanyName','members','loadError','paymentAgreements'));} public function bulkSaveRow():void{$this->guard('products.bulk');header('Content-Type: application/json; charset=UTF-8');$fail=static function(string $message,int $status=422):void{http_response_code($status);echo json_encode(['success'=>false,'message'=>$message],JSON_UNESCAPED_UNICODE);};$token=(string)($_POST['_csrf']??'');if($token===''||!hash_equals(Security::csrf(),$token)){$fail('نشست معتبر نیست؛ صفحه را تازه‌سازی کنید.',419);return;}$companyCode=trim((string)($_POST['company_code']??''));$productCode=trim((string)($_POST['product_code']??''));$agreementIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['payment_agreement_ids']??[])),static fn(int $id):bool=>$id>0)));$priceText=str_replace(',','',trim((string)($_POST['final_price']??'')));if($companyCode===''||$productCode===''||!$agreementIds||$priceText===''||!is_numeric($priceText)||(float)$priceText<=0){$fail('مبلغ نهایی و حداقل یک توافق پرداخت را به‌درستی انتخاب کنید.');return;}$pdo=Database::connection();$companyQuery=$pdo->prepare('SELECT TOP 1 listname FROM dbo.SupplierCO WHERE listcode=:code');$companyQuery->execute(['code'=>$companyCode]);$companyName=$companyQuery->fetchColumn();if($companyName===false){$fail('شرکت انتخاب‌شده معتبر نیست.');return;}try{$service=RahkaranPriceService::instance();$members=$service->partGroupMembers($companyCode);$valid=false;foreach($members as $member){if(trim((string)($member['code']??''))===$productCode){$valid=true;break;}}if(!$valid){$fail('این کالا متعلق به شرکت انتخاب‌شده نیست.');return;}$agreements=$service->paymentAgreements();$validAgreementIds=array_fill_keys(array_map(static fn(array $agreement):int=>(int)($agreement['PaymentAgreementID']??0),$agreements),true);foreach($agreementIds as $agreementId){if(!isset($validAgreementIds[$agreementId])){$fail('یکی از توافق‌های پرداخت انتخاب‌شده معتبر نیست.');return;}}$unitId=$service->unitIdByCode($productCode);if($unitId===null){$fail('واحد کالا در راهکاران پیدا نشد.');return;}$price=round((float)$priceText,2);$insert=$pdo->prepare('INSERT INTO dbo.ProductPriceMonitor(ProductCode,InquiryDate,Source,Price,UnitID,PaymentAgreementID,discountperc,grossprice,opration,netamount,payagrementperc,userid,isexported,Approved,CreatedDate) VALUES(:code,CONVERT(date,GETDATE()),:source,:price,:unit,:agreement,0,:gross,1,:net,0,:userid,0,0,GETDATE())');$pdo->beginTransaction();try{foreach($agreementIds as $agreementId){$insert->execute(['code'=>$productCode,'source'=>(string)$companyName,'price'=>$price,'unit'=>$unitId,'agreement'=>$agreementId,'gross'=>$price,'net'=>$price,'userid'=>Auth::userId()]);}$pdo->commit();}catch(\Throwable $insertError){if($pdo->inTransaction())$pdo->rollBack();throw $insertError;}AuditService::log(Auth::userId(),'price.monitor.company.create','ProductPriceMonitor',$productCode,null,['company_code'=>$companyCode,'price'=>$price,'payment_agreement_ids'=>$agreementIds]);echo json_encode(['success'=>true,'message'=>'ثبت شد','agreement_count'=>count($agreementIds)],JSON_UNESCAPED_UNICODE);return;}catch(\Throwable $e){error_log('Company row price save failed: '.$e->getMessage());$fail('ثبت ردیف در دیتابیس ناموفق بود.',500);return;}} public function bulkApply():void{$this->guard('products.bulk');Security::verifyCsrf();$ids=array_values(array_filter(array_map('intval',(array)($_POST['ids']??[]))));$action=(string)($_POST['action']??'');if(!$ids)exit('حداقل یک محصول انتخاب کنید.');$pdo=Database::connection();$in=implode(',',array_fill(0,count($ids),'?'));$params=$ids;if($action==='activate'||$action==='deactivate'){$v=$action==='activate'?1:0;$s=$pdo->prepare("UPDATE products SET is_active=?,status=?,updated_at=SYSDATETIME() WHERE id IN ($in)");array_unshift($params,$v,$v?'active':'inactive');$s->execute($params);}elseif($action==='importance'){$v=max(1,min(3,(int)($_POST['importance']??1)));$s=$pdo->prepare("UPDATE products SET importance=?,updated_at=SYSDATETIME() WHERE id IN ($in)");array_unshift($params,$v);$s->execute($params);}elseif($action==='assign_queue'||$action==='followup'){$uid=(int)($_POST['assigned_to']??0);$status=$action==='followup'?'needs_followup':'new';$s=$pdo->prepare("UPDATE price_queue SET assigned_to=?,status=?,updated_at=SYSDATETIME() WHERE product_id IN ($in)");array_unshift($params,$uid?:null,$status);$s->execute($params);}elseif($action==='export'){$s=$pdo->prepare("SELECT product_code,product_name,importance,is_active,status FROM products WHERE id IN ($in) ORDER BY product_code");$s->execute($params);$this->csv($s->fetchAll(PDO::FETCH_NUM),['کد','نام','اهمیت','فعال','وضعیت'],'products-bulk.csv');}else exit('عملیات نامعتبر است.');AuditService::log(Auth::userId(),'products.bulk','product',null,null,['action'=>$action,'ids'=>$ids]);Security::redirect('/products/bulk');}
 public function productSources(int $id):void{$this->guard('product.sources.view');$pdo=Database::connection();$s=$pdo->prepare('SELECT id,product_code,product_name FROM products WHERE id=:id');$s->execute(['id'=>$id]);$product=$s->fetch();if(!$product)exit('محصول یافت نشد.');$suppliers=$pdo->query('SELECT id,code,name,is_active FROM suppliers ORDER BY name')->fetchAll();$s=$pdo->prepare('SELECT ps.supplier_id,ps.source_no,ps.expected,ps.is_active FROM product_sources ps WHERE ps.product_id=:id');$s->execute(['id'=>$id]);$sources=[];foreach($s->fetchAll() as $r)$sources[(int)$r['supplier_id']]=$r;View::render('advanced/product-sources',compact('product','suppliers','sources'));}
 public function saveProductSources(int $id):void{$this->guard('product.sources.manage');Security::verifyCsrf();$pdo=Database::connection();$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM product_sources WHERE product_id=:id')->execute(['id'=>$id]);$s=$pdo->prepare('INSERT INTO product_sources(product_id,supplier_id,source_no,expected,is_active) VALUES(:p,:s,:n,:e,1)');foreach((array)($_POST['sources']??[]) as $sid=>$r){$sid=(int)$sid;$n=max(1,min(99,(int)($r['source_no']??1)));$e=!empty($r['expected'])?1:0;if($sid>0)$s->execute(['p'=>$id,'s'=>$sid,'n'=>$n,'e'=>$e]);}$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}AuditService::log(Auth::userId(),'product.sources.update','product',(string)$id);Security::redirect('/admin/product-sources/'.$id);}
 public function workflow():void{$this->guard('workflow.view');$pdo=Database::connection();$steps=$pdo->query('SELECT * FROM workflow_steps WHERE is_active=1 ORDER BY sort_order')->fetchAll();$rows=$pdo->query("SELECT TOP 300 p.id,p.product_code,p.product_name,w.id workflow_id,w.status workflow_status,s.name step_name,w.assigned_to,u.name assigned_name,w.comment,w.started_at,w.completed_at FROM products p LEFT JOIN price_workflow w ON w.id=(SELECT TOP 1 x.id FROM price_workflow x WHERE x.product_id=p.id ORDER BY x.created_at DESC) LEFT JOIN workflow_steps s ON s.id=w.step_id LEFT JOIN users u ON u.id=w.assigned_to WHERE p.is_active=1 ORDER BY p.product_code")->fetchAll();$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();View::render('advanced/workflow',compact('rows','steps','users'));}
 public function workflowStart():void{$this->guard('workflow.manage');Security::verifyCsrf();$pid=(int)($_POST['product_id']??0);$step=(int)($_POST['step_id']??0);$uid=(int)($_POST['assigned_to']??0);$id=WorkflowService::start($pid,$step,$uid?:null);AuditService::log(Auth::userId(),'workflow.start','workflow',(string)$id);Security::redirect('/workflow');}
 public function workflowUpdate(int $id):void{$this->guard('workflow.manage');Security::verifyCsrf();$status=(string)($_POST['status']??'completed');$comment=trim((string)($_POST['comment']??''));$pdo=Database::connection();if($status==='completed')WorkflowService::complete($id,$comment);else{$s=$pdo->prepare('UPDATE price_workflow SET status=:s,comment=:c,updated_at=SYSDATETIME() WHERE id=:id');$s->execute(['s'=>$status,'c'=>$comment?:null,'id'=>$id]);}AuditService::log(Auth::userId(),'workflow.update','workflow',(string)$id,null,['status'=>$status,'comment'=>$comment]);Security::redirect('/workflow');}
 public function queueSettings():void{$this->guard('queue.settings');$keys=['queue.fresh_days'=>'شروع فرسودگی قیمت','queue.fresh_days_15'=>'آستانه امتیاز ۱۵ روز','queue.fresh_days_30'=>'آستانه امتیاز ۳۰ روز','queue.min_sources'=>'حداقل منابع','queue.spread_percent'=>'آستانه اختلاف درصد','queue.score_fresh_7'=>'امتیاز شروع فرسودگی','queue.score_fresh_15'=>'امتیاز آستانه دوم','queue.score_fresh_30'=>'امتیاز آستانه سوم'];$pdo=Database::connection();$s=$pdo->query('SELECT setting_key,setting_value FROM system_settings')->fetchAll();$settings=[];foreach($s as $r)$settings[$r['setting_key']]=$r['setting_value'];View::render('advanced/queue-settings',compact('keys','settings'));}
 public function saveQueueSettings():void{$this->guard('queue.settings');Security::verifyCsrf();$pdo=Database::connection();foreach((array)($_POST['settings']??[]) as $k=>$v){$s=$pdo->prepare('MERGE system_settings AS t USING (SELECT :k setting_key,:v setting_value,:u updated_by) s ON t.setting_key=s.setting_key WHEN MATCHED THEN UPDATE SET setting_value=s.setting_value,updated_by=s.updated_by,updated_at=SYSDATETIME() WHEN NOT MATCHED THEN INSERT(setting_key,setting_value,updated_by) VALUES(s.setting_key,s.setting_value,s.updated_by);');$s->execute(['k'=>(string)$k,'v'=>(string)$v,'u'=>Auth::userId()]);}AuditService::log(Auth::userId(),'queue.settings.update','settings');Security::redirect('/admin/queue-settings');}
 public function health():void{$this->guard('system.health');$pdo=Database::connection();$tables=['products','product_prices','price_queue','price_workflow','suppliers','users','audit_logs','notifications','system_jobs','import_jobs'];$counts=[];foreach($tables as $t){$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM dbo.[$t]")->fetchColumn();}$dbSize=(float)$pdo->query("SELECT SUM(size)*8.0/1024 FROM sys.database_files")->fetchColumn();$indexes=(int)$pdo->query("SELECT COUNT(*) FROM sys.indexes WHERE object_id IN(SELECT object_id FROM sys.tables WHERE is_ms_shipped=0) AND index_id>0")->fetchColumn();$health=['php'=>PHP_VERSION,'pdo_sqlsrv'=>extension_loaded('pdo_sqlsrv')?'فعال':'غیرفعال','sqlsrv'=>extension_loaded('sqlsrv')?'فعال':'غیرفعال','session'=>session_status()===PHP_SESSION_ACTIVE?'فعال':'غیرفعال','db_size_mb'=>number_format($dbSize,2),'indexes'=>$indexes];View::render('advanced/health',compact('counts','health'));}
 public function auditSearch():void{$this->guard('audit.view');$q=trim((string)($_GET['q']??''));$action=trim((string)($_GET['action']??''));$user=(int)($_GET['user_id']??0);$pdo=Database::connection();$where=['1=1'];$p=[];if($q!==''){$where[]='(a.entity_id LIKE :q OR a.entity_type LIKE :q OR a.action LIKE :q)';$p['q']='%'.$q.'%';}if($action!==''){$where[]='a.action LIKE :a';$p['a']='%'.$action.'%';}if($user){$where[]='a.user_id=:u';$p['u']=$user;}$s=$pdo->prepare("SELECT TOP 500 a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE ".implode(' AND ',$where).' ORDER BY a.created_at DESC');$s->execute($p);$rows=$s->fetchAll();$users=$pdo->query('SELECT id,username FROM users ORDER BY username')->fetchAll();View::render('advanced/audit',compact('rows','users','q','action','user'));}
 public function export(string $type):never{$this->guard('reports.export');$pdo=Database::connection();switch($type){case'products':$rows=$pdo->query('SELECT p.product_code,p.product_name,u.name,p.importance,p.is_active,p.expected_sources,p.min_sources,p.max_sources,c.name FROM products p JOIN units u ON u.id=p.unit_id LEFT JOIN product_categories c ON c.id=p.category_id ORDER BY p.product_code')->fetchAll(PDO::FETCH_NUM);$this->csv($rows,['کد','نام','واحد','اهمیت','فعال','منابع مورد انتظار','حداقل','حداکثر','دسته'],'products.csv');case'prices':$rows=$pdo->query('SELECT p.product_code,p.product_name,pp.source_no,pp.supplier,pp.package_price,pp.unit_price,pp.price_received_at FROM product_prices pp JOIN products p ON p.id=pp.product_id ORDER BY p.product_code,pp.price_received_at DESC')->fetchAll(PDO::FETCH_NUM);$this->csv($rows,['کد','نام','منبع','تأمین‌کننده','قیمت بسته','قیمت واحد','تاریخ'],'prices.csv');case'queue':$rows=$pdo->query('SELECT p.product_code,p.product_name,q.score,q.priority_level,q.status,q.assigned_to,q.due_at,q.result_note FROM price_queue q JOIN products p ON p.id=q.product_id ORDER BY q.score DESC')->fetchAll(PDO::FETCH_NUM);$this->csv($rows,['کد','نام','امتیاز','اولویت','وضعیت','مسئول','موعد','نتیجه'],'queue.csv');case'history':$rows=$pdo->query('SELECT p.product_code,p.product_name,pp.source_no,pp.supplier,pp.unit_price,pp.price_received_at FROM product_prices pp JOIN products p ON p.id=pp.product_id ORDER BY pp.price_received_at DESC')->fetchAll(PDO::FETCH_NUM);$this->csv($rows,['کد','نام','منبع','تأمین‌کننده','قیمت واحد','تاریخ'],'history.csv');case'suppliers':$rows=$pdo->query('SELECT code,name,phone,email,contact_name,is_active FROM suppliers ORDER BY name')->fetchAll(PDO::FETCH_NUM);$this->csv($rows,['کد','نام','تلفن','ایمیل','تماس','فعال'],'suppliers.csv');default:exit('نوع خروجی نامعتبر است.');}}
 public function excel(string $type):never{$this->guard('reports.export');$map=['products'=>'SELECT p.product_code,p.product_name,u.name unit_name,p.importance,p.is_active FROM products p JOIN units u ON u.id=p.unit_id ORDER BY p.product_code','prices'=>'SELECT p.product_code,p.product_name,pp.source_no,pp.supplier,pp.unit_price,pp.price_received_at FROM product_prices pp JOIN products p ON p.id=pp.product_id ORDER BY pp.price_received_at DESC','queue'=>'SELECT p.product_code,p.product_name,q.score,q.priority_level,q.status FROM price_queue q JOIN products p ON p.id=q.product_id ORDER BY q.score DESC'];$sql=$map[$type]??null;if(!$sql)exit('نوع خروجی نامعتبر است.');$rows=Database::connection()->query($sql)->fetchAll();header('Content-Type:application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition:attachment; filename="'.$type.'.xls"');echo "<table border='1'><tr>";foreach(array_keys($rows[0]??[]) as $h)echo '<th>'.Security::e($h).'</th>';echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.Security::e($v).'</td>';echo '</tr>';}echo '</table>';exit;}
 public function generateNotifications():void{$this->guard('notifications.manage');Security::verifyCsrf();$pdo=Database::connection();$rules=[];foreach($pdo->query('SELECT rule_key,is_enabled,channel FROM notification_rules')->fetchAll() as $r)$rules[$r['rule_key']]=['enabled'=>(bool)$r['is_enabled'],'channel'=>(string)$r['channel']];$users=$pdo->query('SELECT id,email FROM users WHERE is_active=1')->fetchAll();$metrics=['critical'=>[(int)$pdo->query("SELECT COUNT(*) FROM price_queue WHERE priority_level='critical' AND status IN('new','in_progress','needs_followup')")->fetchColumn(),'اولویت بحرانی','تعداد %d آیتم بحرانی در صف وجود دارد.'],'missing_price'=>[(int)$pdo->query("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND NOT EXISTS(SELECT 1 FROM product_prices pp WHERE pp.product_id=p.id)")->fetchColumn(),'محصول بدون قیمت','تعداد %d محصول بدون قیمت وجود دارد.'],'expired_price'=>[(int)$pdo->query("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND EXISTS(SELECT 1 FROM product_prices pp WHERE pp.product_id=p.id) AND DATEDIFF(DAY,(SELECT MAX(x.price_received_at) FROM product_prices x WHERE x.product_id=p.id),SYSDATETIME())>=30")->fetchColumn(),'قیمت منقضی','تعداد %d محصول با قیمت منقضی وجود دارد.'],'incomplete_sources'=>[(int)$pdo->query("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND (SELECT COUNT(*) FROM product_sources ps WHERE ps.product_id=p.id AND ps.expected=1 AND ps.is_active=1)<p.min_sources")->fetchColumn(),'منابع ناقص','تعداد %d محصول با منابع ناقص وجود دارد.'],'price_spread'=>[(int)$pdo->query("SELECT COUNT(*) FROM products p WHERE p.is_active=1 AND EXISTS(SELECT 1 FROM product_prices a WHERE a.product_id=p.id) AND (SELECT AVG(x.unit_price) FROM product_prices x WHERE x.product_id=p.id)>0 AND ((SELECT MAX(x.unit_price) FROM product_prices x WHERE x.product_id=p.id)-(SELECT MIN(x.unit_price) FROM product_prices x WHERE x.product_id=p.id))/(SELECT AVG(x.unit_price) FROM product_prices x WHERE x.product_id=p.id)>=.20")->fetchColumn(),'اختلاف قیمت','تعداد %d محصول با اختلاف قیمت حداقل ۲۰٪ وجود دارد.'],'queue_new'=>[(int)$pdo->query("SELECT COUNT(*) FROM price_queue WHERE status='new' AND created_at>=DATEADD(day,-1,SYSDATETIME())")->fetchColumn(),'آیتم جدید صف','تعداد %d آیتم جدید در صف ایجاد شده است.'],'due_soon'=>[(int)$pdo->query("SELECT COUNT(*) FROM price_queue WHERE status IN('new','in_progress','needs_followup') AND due_at IS NOT NULL AND due_at BETWEEN SYSDATETIME() AND DATEADD(hour,24,SYSDATETIME())")->fetchColumn(),'نزدیک موعد پیگیری','تعداد %d آیتم در ۲۴ ساعت آینده موعد پیگیری دارد.'],'overdue'=>[(int)$pdo->query("SELECT COUNT(*) FROM price_queue WHERE status IN('new','in_progress','needs_followup') AND due_at IS NOT NULL AND due_at<SYSDATETIME()")->fetchColumn(),'تاخیر در پیگیری','تعداد %d آیتم از موعد پیگیری گذشته است.']];foreach($users as $u){foreach($metrics as $type=>$m){if($m[0]<=0||empty($rules[$type]['enabled']))continue;$message=sprintf($m[2],$m[0]);$s=$pdo->prepare("SELECT COUNT(*) FROM notifications WHERE user_id=:u AND type=:t AND message=:m AND created_at>=DATEADD(day,-1,SYSDATETIME())");$s->execute(['u'=>$u['id'],'t'=>$type,'m'=>$message]);if((int)$s->fetchColumn()>0)continue;$channel=$rules[$type]['channel']??'panel';if($channel==='panel')NotificationService::create((int)$u['id'],$type,$m[1],$message);if($channel==='email'&&!empty($u['email']))MailerService::send((string)$u['email'],'Pricing - '.$m[1],$message);}}AuditService::log(Auth::userId(),'notifications.generate');Security::redirect('/notifications');}
 public function sessions():void{$this->guard('security.manage');$pdo=Database::connection();$rows=$pdo->query('SELECT s.id,s.user_id,s.ip_address,s.user_agent,s.created_at,s.last_seen_at,s.expires_at,u.username,u.name FROM active_sessions s JOIN users u ON u.id=s.user_id WHERE s.revoked_at IS NULL AND (s.expires_at IS NULL OR s.expires_at>SYSDATETIME()) ORDER BY s.last_seen_at DESC')->fetchAll();View::render('advanced/sessions',compact('rows'));}
 public function revokeSession(int $id):void{$this->guard('security.manage');Security::verifyCsrf();$s=Database::connection()->prepare('UPDATE active_sessions SET revoked_at=SYSDATETIME() WHERE id=:id');$s->execute(['id'=>$id]);AuditService::log(Auth::userId(),'session.revoke','session',(string)$id);Security::redirect('/admin/sessions');}
 public function notificationSettings():void{$this->guard('notifications.manage');$rows=Database::connection()->query('SELECT * FROM notification_rules ORDER BY rule_key')->fetchAll();View::render('advanced/notification-settings',compact('rows'));}
 public function saveNotificationSettings():void{$this->guard('notifications.manage');Security::verifyCsrf();$pdo=Database::connection();foreach((array)($_POST['rules']??[]) as $k=>$v){$s=$pdo->prepare('UPDATE notification_rules SET is_enabled=:e,channel=:c,updated_by=:u,updated_at=SYSDATETIME() WHERE rule_key=:k');$s->execute(['e'=>!empty($v['enabled'])?1:0,'c'=>in_array(($v['channel']??'panel'),['panel','email'],true)?$v['channel']:'panel','u'=>Auth::userId(),'k'=>(string)$k]);}AuditService::log(Auth::userId(),'notification.settings.update');Security::redirect('/admin/notification-settings');}

 public function importAdvanced():void{$this->guard('imports.view');View::render('advanced/import');}
 public function importPreview():void{$this->guard('imports.preview');Security::verifyCsrf();if(empty($_FILES['file']['tmp_name']))exit('فایل انتخاب نشده است.');$all=SpreadsheetService::rows($_FILES['file']['tmp_name']);if(!$all)exit('فایل خالی است.');$head=array_shift($all);$rows=array_slice($all,0,10);View::render('advanced/import-preview',compact('head','rows'));}
 public function importAdvancedPost():void{$this->guard('imports.manage');Security::verifyCsrf();$type=(string)($_POST['type']??'');if(empty($_FILES['file']['tmp_name']))exit('فایل انتخاب نشده است.');$all=SpreadsheetService::rows($_FILES['file']['tmp_name']);$head=array_shift($all);$map=[];foreach((array)$head as $k=>$v)$map[trim((string)$v)]=$k;$ok=0;$err=0;$details=[];$pdo=Database::connection();$n=0;foreach($all as $row){$n++;try{if($type==='prices'){foreach(['product_code','source_no','supplier','package_price','unit_price','price_received_at'] as $x)if(!isset($map[$x]))throw new \RuntimeException('ستون '.$x.' الزامی است.');$code=trim((string)$row[$map['product_code']]);$s=$pdo->prepare('SELECT id FROM products WHERE product_code=:c');$s->execute(['c'=>$code]);$pid=$s->fetchColumn();if($pid===false)throw new \RuntimeException('محصول '.$code.' یافت نشد.');$date=trim((string)$row[$map['price_received_at']]);if(preg_match('/^\\d{4}[-\\/]\\d{1,2}[-\\/]\\d{1,2}$/',$date))$date=Jalali::toGregorian($date);$s=$pdo->prepare('SELECT id FROM product_prices WHERE product_id=:p AND source_no=:n AND supplier=:s AND price_received_at=:d');$s->execute(['p'=>$pid,'n'=>(int)$row[$map['source_no']],'s'=>trim((string)$row[$map['supplier']]),'d'=>$date]);$existing=$s->fetchColumn();if($existing===false){$s=$pdo->prepare('INSERT INTO product_prices(product_id,source_no,supplier,package_price,unit_price,price_received_at,created_by,created_at,updated_at) VALUES(:p,:n,:s,:pp,:up,:d,:u,SYSDATETIME(),SYSDATETIME())');$s->execute(['p'=>$pid,'n'=>(int)$row[$map['source_no']],'s'=>trim((string)$row[$map['supplier']]),'pp'=>(float)$row[$map['package_price']],'up'=>(float)$row[$map['unit_price']],'d'=>$date,'u'=>Auth::userId()]);}else{$s=$pdo->prepare('UPDATE product_prices SET package_price=:pp,unit_price=:up,created_by=:u,updated_at=SYSDATETIME() WHERE id=:id');$s->execute(['pp'=>(float)$row[$map['package_price']],'up'=>(float)$row[$map['unit_price']],'u'=>Auth::userId(),'id'=>$existing]);}}elseif($type==='suppliers'){$name=trim((string)($row[$map['name']]??''));if($name==='')throw new \RuntimeException('نام تأمین‌کننده الزامی است.');$s=$pdo->prepare('INSERT INTO suppliers(code,name,phone,email,contact_name,notes) VALUES(:c,:n,:p,:e,:cn,:no)');$s->execute(['c'=>trim((string)($row[$map['code']]??''))?:null,'n'=>$name,'p'=>trim((string)($row[$map['phone']]??''))?:null,'e'=>trim((string)($row[$map['email']]??''))?:null,'cn'=>trim((string)($row[$map['contact_name']]??''))?:null,'no'=>trim((string)($row[$map['notes']]??''))?:null]);}else throw new \RuntimeException('نوع Import نامعتبر است.');$ok++;}catch(\Throwable $e){$err++;$details[]='ردیف '.$n.': '.$e->getMessage();}}AuditService::log(Auth::userId(),'import.advanced',null,null,null,['type'=>$type,'success'=>$ok,'errors'=>$err]);View::render('management/import-result',['result'=>['total'=>$ok+$err,'success'=>$ok,'errors'=>$err,'details'=>$details]]);}

 public function saveFilter():void{$this->guard('search.filters.manage');Security::verifyCsrf();$name=trim((string)($_POST['name']??''));$json=(string)($_POST['filter_json']??'{}');if($name==='')exit('نام فیلتر الزامی است.');$s=Database::connection()->prepare('INSERT INTO saved_filters(user_id,name,screen,filter_json) VALUES(:u,:n,:s,:j)');$s->execute(['u'=>Auth::userId(),'n'=>$name,'s'=>'search','j'=>$json]);Security::redirect('/search');}
 public function deleteFilter(int $id):void{$this->guard('search.filters.manage');Security::verifyCsrf();$s=Database::connection()->prepare('DELETE FROM saved_filters WHERE id=:id AND user_id=:u');$s->execute(['id'=>$id,'u'=>Auth::userId()]);Security::redirect('/search');}

}
